// @ts-strict
// Worker of the peak measures (qualita.js): the Rust functions of mzlab-wasm that need no file, only a trace of the page. Separate from the
// worker of the Rust engine (rust-worker.js), so the quality columns and the methods of the limits work with or without ?motore=rust.
// @ts-ignore the engine is generated by wasm-bindgen: it is not in the tree
import init, { detect_peaks, peak_quality, label_peaks, main_peak, flat_window } from "./wasm/mzlab_wasm.js";

const FIELDS = 10;                                      // PEAK_FIELDS of mzlab-wasm
// The page sends the compiled engine first ({ op: "module", module }; module null = compile it here); an operation that arrives first starts init() by itself.
let ready = null;
const start = module => ready || (ready = module ? init({ module_or_path: module }) : init());

onmessage = async ev => {
  const m = ev.data;
  if (m.op === "module") { start(m.module); return; }
  try {
    await start(null);
    if (m.op === "quality") {
      const out = new Float64Array(3);
      const ok = peak_quality(m.rt, m.y, m.lo, m.hi, out);
      postMessage({ id: m.id, v: ok ? Array.from(out) : null });
    } else if (m.op === "detect") {
      const out = new Float64Array(FIELDS * 64);
      const n = detect_peaks(m.rt, m.y, m.mode, out);
      const peaks = [];
      for (let i = 0; i < n; i++) {
        const r = out.subarray(i * FIELDS, (i + 1) * FIELDS);
        peaks.push({ apex: r[0], lo: r[1], hi: r[2], area: r[3], height: r[4], snr: r[5], n: r[6], gaussian: r[7], asymmetry: Number.isNaN(r[8]) ? null : r[8], noise: r[9] });
      }
      postMessage({ id: m.id, v: peaks });
    } else if (m.op === "labels") {
      const out = new Float64Array(4 * 64);
      const n = label_peaks(m.rt, m.y, m.maxN, m.rel, m.snr, !!m.ends, out);
      postMessage({ id: m.id, v: Array.from({ length: n }, (_, i) => ({ apex: out[i * 4], rt: out[i * 4 + 1], height: out[i * 4 + 2], snr: out[i * 4 + 3] })) });
    } else if (m.op === "flat") {
      const out = new Float64Array(3);
      postMessage({ id: m.id, v: flat_window(m.y, m.frac || 0, m.minPts || 0, out) ? Array.from(out) : null });
    } else if (m.op === "mainpeak") {
      const out = new Float64Array(2);
      postMessage({ id: m.id, v: main_peak(m.x, m.y, m.refine, out) ? { x: out[0], y: out[1] } : null });
    } else postMessage({ id: m.id, error: "unknown operation" });
  } catch (e_) { const e = /** @type {Lanciato} */ (e_);
    postMessage({ id: m.id, error: String((e && e.message) || e) });
  }
};
